const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell,
  WidthType, ShadingType, BorderStyle, LevelFormat, AlignmentType, ExternalHyperlink,
  Footer, PageNumber
} = require('docx');

const FONT = 'Calibri';
const ACCENT = '1F4E79';
const W = 9638; // A4 text width with 2cm margins (11906 - 2*1134)

const p = (text, opts = {}) => new Paragraph({
  spacing: { after: 120 },
  ...opts,
  children: Array.isArray(text) ? text : [new TextRun({ text, font: FONT, size: 21 })],
});
const t = (text, o = {}) => new TextRun({ text, font: FONT, size: o.size || 21, bold: o.bold, italics: o.italics, color: o.color });
const h1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 140 }, children: [new TextRun({ text, font: FONT, size: 30, bold: true, color: ACCENT })] });
const h2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 240, after: 100 }, children: [new TextRun({ text, font: FONT, size: 25, bold: true, color: ACCENT })] });
const bullet = (runs) => new Paragraph({ numbering: { reference: 'bul', level: 0 }, spacing: { after: 80 }, children: Array.isArray(runs) ? runs : [t(runs)] });
const link = (label, url) => new ExternalHyperlink({ link: url, children: [new TextRun({ text: label, font: FONT, size: 18, color: '0563C1', underline: {} })] });

const border = { style: BorderStyle.SINGLE, size: 4, color: 'BFBFBF' };
const borders = { top: border, bottom: border, left: border, right: border };
const COLS = [500, 4300, 1900, 2938];

function cell(children, width, shade) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders,
    shading: shade ? { type: ShadingType.CLEAR, color: 'auto', fill: shade } : undefined,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    children,
  });
}
function headerRow() {
  const labels = ['☐', 'Aufgabe', 'Wer', 'Offizielle Quelle'];
  return new TableRow({ tableHeader: true, children: labels.map((l, i) => cell([new Paragraph({ children: [t(l, { bold: true, color: 'FFFFFF', size: 19 })] })], COLS[i], ACCENT)) });
}
// item: {nr, title, text:[strings], who:{label, note}, src:[[label,url,official]]}
function row(it) {
  const who = it.who;
  const whoFill = who.label.startsWith('Mensch') ? 'FCE4D6' : 'E2EFDA';
  const desc = [new Paragraph({ spacing: { after: 60 }, children: [t(`${it.nr}. ${it.title}`, { bold: true })] })]
    .concat(it.text.map(s => new Paragraph({ spacing: { after: 60 }, children: [t(s, { size: 19 })] })));
  const whoCell = [new Paragraph({ spacing: { after: 60 }, children: [t(who.label, { bold: true, size: 19 })] })];
  if (who.note) whoCell.push(new Paragraph({ children: [t(who.note, { size: 18 })] }));
  const srcCell = it.src.map(([label, url, note]) => new Paragraph({ spacing: { after: 60 }, children: [link(label, url)].concat(note ? [t(' ' + note, { size: 17, italics: true, color: '7F7F7F' })] : []) }));
  return new TableRow({ cantSplit: true, children: [
    cell([new Paragraph({ children: [t('☐', { size: 24 })] })], COLS[0]),
    cell(desc, COLS[1]),
    cell(whoCell, COLS[2], whoFill),
    cell(srcCell, COLS[3]),
  ] });
}
const table = (items) => new Table({ width: { size: W, type: WidthType.DXA }, columnWidths: COLS, rows: [headerRow(), ...items.map(row)] });

const S = {
  gewo: ['§ 14 GewO (Gesetze im Internet)', 'https://www.gesetze-im-internet.de/gewo/__14.html'],
  hk: ['Handelskammer Hamburg: Gewerbeanmeldung', 'https://www.handelskammer-hamburg.de/gruendung-sicherung-nachfolge/gewerbe-an-um-melden/gewerbeanmeldung-6598040'],
  lfst: ['LfSt Bayern: Merkblatt steuerliche Erfassung (Juni 2025)', 'https://www.lfst.bayern.de/fileadmin/RESSOURCEN/INFORMATIONEN/Steuerinfos/Zielgruppen/Existenzgruender/Merkblattblatt_zur_steuerlichen_Erfassung_Neugruender_Juni_2025.pdf', '(bundesweites Verfahren, Merkblatt aus Bayern)'],
  fim: ['FIM-Portal: Fragebogen zur steuerlichen Erfassung', 'https://fimportal.de/api/v0/leistung-stammtexte/L100001/365573585/pvog/de/pdf'],
  ust19: ['§ 19 UStG (Gesetze im Internet)', 'https://www.gesetze-im-internet.de/ustg_1980/__19.html'],
  fabw: ['Finanzamt BW: Kleinunternehmerregelung', 'https://finanzamt-bw.fv-bwl.de/,Lde/Startseite/Service/Was+ist+die+sogenannte+Kleinunternehmerregelung_'],
  zsvrReg: ['ZSVR: Registrierung im LUCID-Register', 'https://www.verpackungsregister.org/en/registration/find-out-about-registrations'],
  zsvrOnline: ['ZSVR: Versand- und Onlinehandel', 'https://www.verpackungsregister.org/en/knowledge-bases/mail-order-companies-and-online-retailers'],
  zsvrNew: ['ZSVR: Was seit 12. August 2026 gilt', 'https://www.verpackungsregister.org/en/i-want-to-know-what-changed-on-12-august-2026'],
  printful: ['Printful-Hilfe: VerpackDG / LUCID', 'https://help.printful.com/hc/en-us/articles/360014010680-How-does-the-German-Packaging-Act-VerpackDG-affect-my-business', '(Anbieter, nicht amtlich)'],
  dpma: ['DPMA: Markenrecherche', 'https://dpma.de/marken/markenrecherche'],
  b2b: ['IT-Recht Kanzlei: reiner B2B-Shop', 'https://www.it-recht-kanzlei.de/reiner-b2b-shop-anleitung.html', '(Kanzlei, nicht amtlich)'],
  b2bBgh: ['IT-Recht Kanzlei: BGH zur B2B-Beschränkung', 'https://www.it-recht-kanzlei.de/b2b-.shop-bgh-anforderungen-beschraenkung-erwerberkreis.html', '(Kanzlei, nicht amtlich)'],
  impChem: ['IHK Chemnitz: Impressumspflicht', 'https://www.ihk.de/chemnitz/recht-und-steuern/rechtsinformationen/internetrecht/pflichtangaben-im-internet-die-impressumspflicht-4401580'],
  impMuc: ['IHK München: Impressum', 'https://www.ihk-muenchen.de/ratgeber/recht/internetrecht/impressum/'],
  hmbbfdi: ['HmbBfDI: Datenschutzkonformer Internetauftritt', 'https://datenschutz-hamburg.de/fileadmin/user_upload/HmbBfDI/Datenschutz/Informationen/2023-04-Information_Webseitenbetreiber_innen.pdf'],
  widerrufBtn: ['IHK Köln: Widerrufsfunktion seit Juni 2026', 'https://www.ihk.de/koeln/hauptnavigation/recht-steuern/widerrufsbutton-neue-pflicht-ab-juni-2026-6950888'],
  widerrufAus: ['IT-Recht Kanzlei: Ausnahmen vom Widerrufsrecht', 'https://www.it-recht-kanzlei.de/ausnahmen-widerrufsrecht.html', '(Kanzlei, nicht amtlich)'],
  textil: ['IHK München: Merkblatt Textilkennzeichnung', 'https://www.ihk-muenchen.de/ihk/Medien/Merkblatt-Textilkennzeichnung_2022.pdf'],
  gpsr: ['IHK Köln: Produktsicherheit (GPSR)', 'https://www.ihk.de/koeln/hauptnavigation/recht-steuern/produktsicherheit-6206448'],
  os: ['IHK Stuttgart: OS-Plattform eingestellt', 'https://www.ihk.de/stuttgart/fuer-unternehmen/recht-und-steuern/it-recht/os-plattform-zur-streitbeilegung-wird-eingestellt-6488402'],
};

const phase1 = [
  { nr: 1, title: 'Gewerbe in Hamburg anmelden (zuerst)', text: [
      'Pflicht nach § 14 GewO: Wer ein Gewerbe beginnt, muss es gleichzeitig anzeigen. Zuständig ist das Bezirksamt deines Betriebssitzes; die Handelskammer Hamburg nimmt Anmeldungen ebenfalls an. Gebühr laut Handelskammer: 25 €.',
      'Tätigkeit z. B. „Online-Handel mit bestickter Arbeitskleidung (Herstellung durch Dienstleister auf Bestellung)“ – Formulierung mit dem Amt abstimmen.'],
    who: { label: 'Mensch', note: 'Du reichst ein und zahlst. Claude kann den Tätigkeitstext und eine Ausfüllliste vorbereiten.' }, src: [S.gewo, S.hk] },
  { nr: 2, title: 'ELSTER-Konto + Fragebogen zur steuerlichen Erfassung', text: [
      'Den Fragebogen gibt es nur elektronisch über ELSTER. Frist: ein Monat nach Beginn der Tätigkeit (§ 138 AO). Danach teilt das Finanzamt die Steuernummer mit.',
      'Im Fragebogen kannst du auch eine USt-IdNr. beantragen (laut Merkblatt LfSt Bayern).'],
    who: { label: 'Mensch', note: 'Konto und Absenden nur durch dich. Claude kann einen Antwortzettel mit deinen Zahlen vorbereiten.' }, src: [S.lfst, S.fim] },
  { nr: 3, title: 'Entscheiden: Kleinunternehmer oder nicht', text: [
      'Kleinunternehmerregelung (§ 19 UStG): Vorjahresumsatz max. 25.000 €, laufendes Jahr max. 100.000 €. Freiwilliger Verzicht ist möglich (§ 19 Abs. 3 UStG). Die Wahl triffst du im Fragebogen.',
      'Folge für die Website: Als Kleinunternehmer weist du keine USt aus, das Wort „brutto“ muss weg. Ohne Kleinunternehmer stecken in 109 € rund 91,60 € netto, in 29,90 € rund 25,13 € netto (bei 19 %).'],
    who: { label: 'Mensch', note: 'Entscheidung mit Steuerberater. Claude kann beide Varianten mit deinen Kosten durchrechnen.' }, src: [S.ust19, S.fabw] },
  { nr: 4, title: 'Entscheiden: nur an Firmen (B2B) oder auch an Verbraucher', text: [
      'Diese Entscheidung bestimmt fast alle Website-Texte in Phase 3 (Widerruf, Preisangaben, AGB, Produktangaben).',
      'Ein bloßer Hinweis „nur B2B“ reicht laut Kanzlei-Quellen nicht; nötig sind klare Hinweise auf jeder Seite und eine Bestätigung im Bestellprozess. Eine Behördenquelle dazu habe ich nicht gefunden.'],
    who: { label: 'Mensch', note: 'Geschäftsentscheidung. Claude kann die Folgen beider Wege gegenüberstellen und die Hinweise in die Seite einbauen.' }, src: [S.b2b, S.b2bBgh] },
  { nr: 5, title: 'Name „Kolonnenshirt“ prüfen (DPMA, EUIPO)', text: [
      'Das DPMA prüft bei einer Anmeldung keine älteren Rechte Dritter; das musst du selbst recherchieren. DPMAregister ist kostenlos. Der Name geht später auch als Markenname ins LUCID-Register.'],
    who: { label: 'Mensch', note: 'Rechtliche Bewertung durch Markenanwalt. Claude kann eine erste Websuche nach gleichen Namen machen, das ist keine Ähnlichkeitsrecherche.' }, src: [S.dpma] },
];

const phase2 = [
  { nr: 6, title: 'Im Verpackungsregister LUCID registrieren', text: [
      'Seit 12. August 2026 gelten die EU-Verpackungsverordnung (PPWR) und das VerpackDG. Printful schreibt, dass Händler sich jetzt unter eigenem Namen registrieren müssen, auch wenn Printful alle Bestellungen versendet; die Printful-Nummer reicht nicht mehr.',
      'Die Registrierung ist kostenlos. Laut ZSVR werden Stammdaten wie USt-IdNr. bzw. Steuernummer abgefragt – deshalb erst nach Schritt 2.',
      'Laut ZSVR ist Versandverpackung ausnahmslos systembeteiligungspflichtig, auch beim Versand an Gewerbekunden.'],
    who: { label: 'Mensch', note: 'Laut ZSVR persönliche Pflicht des Unternehmens. Claude kann die Datenliste vorbereiten.' }, src: [S.zsvrReg, S.zsvrNew, S.zsvrOnline, S.printful] },
  { nr: 7, title: 'Vertrag mit einem dualen System + Mengenmeldung', text: [
      'Vor dem ersten Inverkehrbringen Systembeteiligung abschließen und die Verpackungsmengen melden. Material, Gewicht und Volumen der Printful-Verpackung musst du beim Lieferanten erfragen. Printful übernimmt laut eigener Aussage die Kosten für seine eigene Verpackung – wie das mit deiner Pflicht zusammenspielt, unbedingt klären (siehe „Was ich nicht prüfen konnte“).'],
    who: { label: 'Mensch', note: 'Vertrag schließt du. Claude kann die Systembetreiber-Liste der ZSVR mit dir durchgehen.' }, src: [S.zsvrOnline, S.printful] },
];

const phase3 = [
  { nr: 8, title: 'Impressum (§ 5 DDG)', text: [
      'Seit 14.05.2024 steht die Pflicht in § 5 DDG statt TMG. Mindestens Name, ladungsfähige Anschrift, schnelle elektronische Kontaktaufnahme (laut IHK Telefon und E-Mail), ggf. USt-IdNr.; die Steuernummer gehört nicht hinein.'],
    who: { label: 'Claude', note: 'Entwurf und Einbau, sobald du die Daten lieferst. Prüfung durch Anwalt empfohlen.' }, src: [S.impChem, S.impMuc] },
  { nr: 9, title: 'Datenschutzerklärung (Art. 13 DSGVO)', text: [
      'Inhalt hängt von den eingesetzten Diensten ab (Shop-System, Zahlung, Formular, Schriften, Hosting). Schrift Inter am besten selbst hosten statt von Google laden.'],
    who: { label: 'Claude', note: 'Dienste-Liste, Entwurf, Schrift selbst hosten. Rechtliche Prüfung durch Mensch.' }, src: [S.hmbbfdi] },
  { nr: 10, title: 'Nur bei Verbrauchern: Widerrufsbelehrung + Widerrufsbutton', text: [
      'Seit 19. Juni 2026 brauchen Online-Shops mit Verbraucherverträgen eine elektronische Widerrufsfunktion (§ 356a BGB).',
      'Bei Ware nach Kundenspezifikation (z. B. Kundenlogo) ist das Widerrufsrecht nach § 312g Abs. 2 Nr. 1 BGB ausgeschlossen; laut EuGH auch schon vor Produktionsbeginn. Ob deine Shirts darunter fallen, prüfen lassen.',
      'Bei reinem B2B entfallen beide Punkte.'],
    who: { label: 'Mensch', note: 'Rechtstexte durch Anwalt oder Händlerverband. Claude kann den Button technisch einbauen.' }, src: [S.widerrufBtn, S.widerrufAus] },
  { nr: 11, title: 'AGB passend zur B2B/B2C-Entscheidung', text: [
      'Bei reinem B2B: AGB dürfen nicht zusätzlich Verbraucher ansprechen, sonst wird die Beschränkung aufgeweicht (Kanzlei-Quelle).'],
    who: { label: 'Mensch', note: 'Anwalt oder Rechtstexte-Dienst. Claude kann einbinden.' }, src: [S.b2b] },
  { nr: 12, title: 'Preis- und Produktangaben auf der Seite', text: [
      'USt-Formulierung nach Schritt 3; Versandkosten und Lieferzeit beim Preis (aus deinem letzten Ergebnis).',
      'Faserzusammensetzung muss Verbrauchern vor dem Kauf angezeigt werden (EU-Textilkennzeichnungsverordnung).',
      'Wenn die Shirts Verbraucherprodukte sind: Herstellerangaben und ggf. Sicherheitshinweise im Angebot (GPSR, Art. 19). Wer eigene Marke führt, kann als Hersteller gelten.'],
    who: { label: 'Claude', note: 'Texte einbauen, sobald du Material und Herstellerdaten von Printful lieferst.' }, src: [S.textil, S.gpsr] },
  { nr: 13, title: 'Keinen Link zur OS-Plattform einbauen', text: [
      'Die EU-Plattform zur Online-Streitbeilegung ist seit 20. Juli 2025 abgeschaltet; Hinweise darauf sollen entfernt werden. Andere Hinweise zur Verbraucherstreitbeilegung (§ 36 VSBG) können weiter nötig sein – prüfen lassen.'],
    who: { label: 'Claude', note: 'Sicherstellen, dass nichts davon auf der Seite steht.' }, src: [S.os] },
];

const notChecked = [
  'Deine persönliche Lage: Ich kenne weder deine Rechtsform noch ob du nebenberuflich startest. Ich bin von einem Einzelunternehmen ausgegangen.',
  'Wer genau beim Verpackungsrecht „Hersteller“ und „Erzeuger“ ist: Printful sagt, du musst dich registrieren. Die ZSVR-Regeln hängen aber von Branding, Lieferkette und Sitz von Printful ab. Das konnte ich nicht abschließend klären; frag direkt bei der ZSVR oder einem Anwalt nach.',
  'Ob die Produktsicherheitsverordnung (GPSR) bei reinem B2B-Verkauf greift: Sie gilt für Verbraucherprodukte. Ob Arbeitsshirts dazu zählen, wenn Betriebe sie kaufen, habe ich nicht geprüft.',
  'Ob die Ausnahme vom Widerrufsrecht für deine Shirts gilt: Die Quellen dazu sind Kanzlei-Artikel, keine Behörde.',
  'Den offiziellen Hamburg-Service-Eintrag zur Gewerbeanmeldung konnte ich nicht direkt öffnen. Gebühr und Zuständigkeit stammen von der Handelskammer Hamburg.',
  'Ob § 36 VSBG (Hinweis zur Verbraucherschlichtung) für dich gilt und welcher Text nötig ist.',
  'Weitere mögliche Pflichten, die ich nicht recherchiert habe: Handwerkskammer (die Stickerei macht Printful, nicht du), Berufsgenossenschaft, Krankenversicherung, Gewerbesteuer, EUIPO-Recherche, aktuelle Printful-AGB, Lizenz der Schrift Inter, Rechtsfragen zum Sticken fremder Kundenlogos.',
  'Kein Ergebnis hier ist Rechts- oder Steuerberatung. Ich bin kein Anwalt und kein Steuerberater.',
];

const doc = new Document({
  creator: 'Claude',
  title: 'Kolonnenshirt – Checkliste vor dem ersten Verkauf',
  styles: { default: { document: { run: { font: FONT, size: 21 } } } },
  numbering: { config: [{ reference: 'bul', levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 360, hanging: 260 } } } }] }] },
  sections: [{
    properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1134, bottom: 1134, left: 1134, right: 1134 } } },
    footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [t('Stand: 29. Oktober 2026 · Seite ', { size: 16, color: '7F7F7F' }), new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: 16, color: '7F7F7F' })] })] }) },
    children: [
      new Paragraph({ spacing: { after: 80 }, children: [new TextRun({ text: 'Kolonnenshirt', font: FONT, size: 40, bold: true, color: ACCENT })] }),
      p([t('Checkliste: Was vor dem ersten verkauften Shirt angemeldet oder geklärt sein muss', { size: 26 })]),
      p([t('Stand 29. Oktober 2026. Recherchiert per Websuche, keine Rechts- oder Steuerberatung. Behördenquellen sind direkt verlinkt; Kanzlei- und Anbieterquellen sind als „nicht amtlich“ gekennzeichnet.', { size: 19, italics: true, color: '595959' })]),

      h1('Was als Erstes kommt: die Gewerbeanmeldung'),
      p('Drei Gründe:'),
      bullet([t('Sie ist die gesetzliche Voraussetzung. ', { bold: true }), t('§ 14 GewO verlangt die Anzeige gleichzeitig mit dem Beginn des Gewerbes. Ohne sie verkaufst du das erste Shirt nicht rechtmäßig.')]),
      bullet([t('Sie schaltet die anderen Schritte frei. ', { bold: true }), t('Danach folgt der Fragebogen beim Finanzamt und damit die Steuernummer. Die braucht die LUCID-Registrierung als Stammdatum, und dein USt-Status entscheidet, wie der Preis auf der Seite stehen darf.')]),
      bullet([t('Sie ist schnell und günstig. ', { bold: true }), t('25 € in Hamburg, einreichbar beim Bezirksamt oder bei der Handelskammer. Kein anderer Punkt der Liste hängt an so wenig Vorarbeit.')]),
      p([t('Parallel dazu solltest du die Frage „nur an Firmen?“ entscheiden (Punkt 4), weil sie fast alle Website-Texte bestimmt.', { italics: true })]),

      h2('Legende'),
      p([t('Mensch', { bold: true }), t(' = nur du (oder ein Anwalt/Steuerberater) kannst es erledigen: Unterschrift, Konto, Entscheidung oder rechtliche Prüfung.   '), t('Claude', { bold: true }), t(' = ich kann es mit deinen Angaben erstellen oder in die Seite einbauen.')]),

      h1('Phase 1 · Anmelden und entscheiden (jetzt)'),
      table(phase1),
      h1('Phase 2 · Verpackung (nach der Steuernummer, vor dem ersten Versand)'),
      table(phase2),
      h1('Phase 3 · Website, bevor sie online geht'),
      table(phase3),

      h1('Was ich nicht prüfen konnte'),
      ...notChecked.map(s => bullet(s)),
    ],
  }],
});

Packer.toBuffer(doc).then(b => { fs.writeFileSync('/home/claude/Kolonnenshirt_Checkliste_erster_Verkauf.docx', b); console.log('written'); });
